const env={PATH:process.env.PATH||'/usr/bin:/bin',LANG:'C.UTF-8'};
if(process.env.REPL_ID)env.REPL_ID=process.env.REPL_ID;
const result=spawnSync(process.execPath,[path.join(directory,names[0])],{stdio:'inherit',env});
